"""Pure validation and row-mapping helpers for TaskBoard."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

VALID_STATUSES = ("todo", "doing", "done")
VALID_PRIORITIES = ("low", "medium", "high")


def validate_project_name(name: str) -> str:
    """Trim and validate a project name."""
    if not isinstance(name, str):
        raise ValueError("project name must be a string")
    value = name.strip()
    if not value:
        raise ValueError("project name cannot be empty")
    if len(value) > 80:
        raise ValueError("project name cannot exceed 80 characters")
    return value


def validate_task_fields(
    title: str,
    description: str = "",
    priority: str = "medium",
    status: str = "todo",
) -> dict[str, str]:
    """Validate and normalize task fields for persistence."""
    if not isinstance(title, str):
        raise ValueError("task title must be a string")
    normalized_title = title.strip()
    if not normalized_title:
        raise ValueError("task title cannot be empty")
    if len(normalized_title) > 120:
        raise ValueError("task title cannot exceed 120 characters")
    if not isinstance(description, str):
        raise ValueError("description must be a string")
    if len(description) > 1000:
        raise ValueError("description cannot exceed 1000 characters")
    if priority not in VALID_PRIORITIES:
        raise ValueError("invalid priority")
    if status not in VALID_STATUSES:
        raise ValueError("invalid status")
    return {
        "title": normalized_title,
        "description": description,
        "priority": priority,
        "status": status,
    }


def _mapping(row: Mapping[str, Any] | Any) -> dict[str, Any]:
    if isinstance(row, Mapping):
        return dict(row)
    keys = row.keys()
    return {key: row[key] for key in keys}


def project_from_row(row: Mapping[str, Any] | Any) -> dict[str, Any]:
    """Map a database row to the public project representation."""
    values = _mapping(row)
    return {
        "id": values["id"],
        "name": values["name"],
        "created_at": values["created_at"],
    }


def task_from_row(row: Mapping[str, Any] | Any) -> dict[str, Any]:
    """Map a database row to the public task representation."""
    values = _mapping(row)
    return {
        "id": values["id"],
        "project_id": values["project_id"],
        "title": values["title"],
        "description": values["description"],
        "status": values["status"],
        "priority": values["priority"],
        "created_at": values["created_at"],
        "updated_at": values["updated_at"],
    }
